{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic does not specify a customer-managed encryption key (CMEK). Without CMEK, data is encrypted using Google-managed keys, which may not meet compliance or security requirements for sensitive data."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_queue\" {\n  name = \"insurance-claims-processing-platform-pubsub-notifications\"\n  labels = {\n    environment = \"production\"\n    component   = \"notifications\"\n  }\n  kms_key_name = \"projects/my-project/locations/global/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added the `kms_key_name` attribute to enable encryption of the PubSub topic with a Customer Supplied Encryption Key (CSEK)."
}
